const message = $input.first().json.message;
if (!message) return [];
const messageDate = message.date;
const now = Math.floor(Date.now() / 1000);
if (now - messageDate > 60) return [];
return [{ json: $input.first().json }];

const message = $input.first().json.message.text;
const match = message.match(/mangadex\.org\/chapter\/([a-f0-9-]+)/i);

if (!match) throw new Error('Could not extract chapter ID');

// --- BGM LIBRARY (all tracks) ---
const allBgmTracks = [
