  "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/bgm/Banda%20Kaam%20Ka%20pagalall.com.mp3"
];

// Random BGM selection
const bgmUrl = allBgmTracks[Math.floor(Math.random() * allBgmTracks.length)];
const bgmName = bgmUrl.split('/').pop().replace('.mp3','').replace(/%20/g,' ');
const outroUrl = "https://pub-3edc2a55a5af4b14b554c8ed89ceadb7.r2.dev/outro.jpg";

return [{
  json: {
    chapterId: match[1],
    chatId: String($input.first().json.message.chat.id),
    bgmUrl: bgmUrl,
    bgmName: bgmName,
    outroUrl: outroUrl
  }
}];

const raw = $input.first().json.data || '';
const m = raw.match(/data:\s*\[([^\]]+)\]/g);
if (m && m.length) {
  const p = JSON.parse(m[m.length-1].replace('data: ',''));
  const v = p[1];
  const s = p[0] || '';
  const tm = s.match(/Done!\s*(.+?)\s*-\s*Ch\./i);
  const cm = s.match(/Ch\.?(\d+)/i);
  return [{json: {
    status: s,
    mangaTitle: tm ? tm[1].trim() : 'Manga',
    chapterNum: cm ? cm[1] : '',
    video_url: v?.url || v,
    chatId: $('Extract Chapter ID').first().json.chatId,
    bgmName: $('Extract Chapter ID').first().json.bgmName
  }}];
}
return [{json: {error: 'Parse failed', chatId: $('Extract Chapter ID').first().json.chatId}}];
